/**
 * psl_free:
 * @psl: PSL context pointer
 *
 * This function frees the the PSL context that has been retrieved via
 * psl_load_fp() or psl_load_file().
 *
 * Since: 0.1
 */
void psl_free(psl_ctx_t *psl)
{
        if (psl && psl != &builtin_psl) {
                vector_free(&psl->suffixes);
                free(psl->dafsa);
                free(psl);
        }
}

